use std::process::ExitCode;

use wgpu::util::DeviceExt;

const WORKGROUP: u32 = 64;

const SHADER: &str = r#"
struct Params {
    count: u32,
    dt: f32,
    _pad0: u32,
    _pad1: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> vel: array<vec2<f32>>;
@group(0) @binding(3) var<storage, read_write> acc: array<vec2<f32>>;

// Part 1: every acceleration from the positions the step started with.
@compute @workgroup_size(64)
fn accelerate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let pi = pos[i];
    var a = vec2<f32>(0.0, 0.0);
    for (var j = 0u; j < params.count; j = j + 1u) {
        if (j == i) {
            continue;
        }
        let d = pos[j] - pi;
        let s = dot(d, d) + 0.01;
        a = a + d / (s * sqrt(s));
    }
    acc[i] = a;
}

// Part 2: velocity grows by acceleration * dt, then position by new velocity * dt.
@compute @workgroup_size(64)
fn integrate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let v = vel[i] + acc[i] * params.dt;
    vel[i] = v;
    pos[i] = pos[i] + v * params.dt;
}
"#;

#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
struct Params {
    count: u32,
    dt: f32,
    _pad0: u32,
    _pad1: u32,
}

struct Input {
    steps: u32,
    dt: f32,
    pos: Vec<[f32; 2]>,
    vel: Vec<[f32; 2]>,
}

fn parse(text: &str) -> Result<Input, String> {
    let mut tokens = text.split_whitespace();
    let mut next = |what: &str| tokens.next().ok_or_else(|| format!("missing {what}"));

    let count_tok = next("count")?;
    let count: usize = count_tok
        .parse()
        .map_err(|_| format!("bad count: {count_tok}"))?;
    if !(1..=2048).contains(&count) {
        return Err(format!("count out of range: {count}"));
    }
    let steps_tok = next("steps")?;
    let steps: u32 = steps_tok
        .parse()
        .map_err(|_| format!("bad steps: {steps_tok}"))?;
    if steps > 200 {
        return Err(format!("steps out of range: {steps}"));
    }
    let dt_tok = next("dt")?;
    let dt: f64 = dt_tok.parse().map_err(|_| format!("bad dt: {dt_tok}"))?;

    let mut pos = Vec::with_capacity(count);
    let mut vel = Vec::with_capacity(count);
    for k in 0..count {
        let mut field = [0f32; 4];
        for f in field.iter_mut() {
            let tok = next(&format!("field of particle {}", k + 1))?;
            let value: f64 = tok.parse().map_err(|_| format!("bad number: {tok}"))?;
            *f = value as f32;
        }
        pos.push([field[0], field[1]]);
        vel.push([field[2], field[3]]);
    }
    Ok(Input {
        steps,
        dt: dt as f32,
        pos,
        vel,
    })
}

fn simulate(input: &Input) -> Result<(Vec<[f32; 2]>, Vec<[f32; 2]>), String> {
    pollster::block_on(simulate_async(input))
}

async fn simulate_async(input: &Input) -> Result<(Vec<[f32; 2]>, Vec<[f32; 2]>), String> {
    let count = input.pos.len();
    let bytes = (count * std::mem::size_of::<[f32; 2]>()) as u64;

    let instance = wgpu::Instance::default();
    let adapter = match instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            ..Default::default()
        })
        .await
    {
        Ok(adapter) => adapter,
        Err(_) => instance
            .request_adapter(&wgpu::RequestAdapterOptions {
                force_fallback_adapter: true,
                ..Default::default()
            })
            .await
            .map_err(|e| format!("no GPU adapter: {e}"))?,
    };
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default())
        .await
        .map_err(|e| format!("no GPU device: {e}"))?;

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("particles"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });

    let params = Params {
        count: count as u32,
        dt: input.dt,
        _pad0: 0,
        _pad1: 0,
    };
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::bytes_of(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let storage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC;
    let pos_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("pos"),
        contents: bytemuck::cast_slice(&input.pos),
        usage: storage,
    });
    let vel_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("vel"),
        contents: bytemuck::cast_slice(&input.vel),
        usage: storage,
    });
    let acc_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("acc"),
        size: bytes,
        usage: wgpu::BufferUsages::STORAGE,
        mapped_at_creation: false,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: bytes * 2,
        usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
        mapped_at_creation: false,
    });

    let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("particles"),
        entries: &[
            layout_entry(0, wgpu::BufferBindingType::Uniform),
            layout_entry(1, wgpu::BufferBindingType::Storage { read_only: false }),
            layout_entry(2, wgpu::BufferBindingType::Storage { read_only: false }),
            layout_entry(3, wgpu::BufferBindingType::Storage { read_only: false }),
        ],
    });
    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("particles"),
        layout: &layout,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: params_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: pos_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 2,
                resource: vel_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 3,
                resource: acc_buf.as_entire_binding(),
            },
        ],
    });
    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("particles"),
        bind_group_layouts: &[Some(&layout)],
        ..Default::default()
    });
    let pipeline = |entry: &str| {
        device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some(entry),
            layout: Some(&pipeline_layout),
            module: &module,
            entry_point: Some(entry),
            compilation_options: Default::default(),
            cache: None,
        })
    };
    let accelerate = pipeline("accelerate");
    let integrate = pipeline("integrate");

    let groups = (count as u32).div_ceil(WORKGROUP);
    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
    for _ in 0..input.steps {
        // Separate passes so every acceleration is computed before any position moves.
        for stage in [&accelerate, &integrate] {
            let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor::default());
            pass.set_pipeline(stage);
            pass.set_bind_group(0, &bind_group, &[]);
            pass.dispatch_workgroups(groups, 1, 1);
        }
    }
    encoder.copy_buffer_to_buffer(&pos_buf, 0, &readback, 0, bytes);
    encoder.copy_buffer_to_buffer(&vel_buf, 0, &readback, bytes, bytes);
    queue.submit([encoder.finish()]);

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("readback lost: {e}"))?
        .map_err(|e| format!("readback failed: {e}"))?;

    let data = slice.get_mapped_range();
    let floats: &[[f32; 2]] = bytemuck::cast_slice(&data);
    let pos = floats[..count].to_vec();
    let vel = floats[count..].to_vec();
    drop(data);
    readback.unmap();
    Ok((pos, vel))
}

fn layout_entry(binding: u32, ty: wgpu::BufferBindingType) -> wgpu::BindGroupLayoutEntry {
    wgpu::BindGroupLayoutEntry {
        binding,
        visibility: wgpu::ShaderStages::COMPUTE,
        ty: wgpu::BindingType::Buffer {
            ty,
            has_dynamic_offset: false,
            min_binding_size: None,
        },
        count: None,
    }
}

fn fmt(value: f64) -> String {
    let s = format!("{value:.6}");
    if s == "-0.000000" { "0.000000".into() } else { s }
}

fn run() -> Result<(), String> {
    let path = std::env::args()
        .nth(1)
        .ok_or("usage: gpu_particles <input-file>")?;
    let text = std::fs::read_to_string(&path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let input = parse(&text)?;
    let (pos, vel) = simulate(&input)?;

    let n = pos.len() as f64;
    let (mut cx, mut cy) = (0f64, 0f64);
    for p in &pos {
        cx += p[0] as f64;
        cy += p[1] as f64;
    }
    cx /= n;
    cy /= n;
    let (mut px, mut py, mut kinetic) = (0f64, 0f64, 0f64);
    for v in &vel {
        let (vx, vy) = (v[0] as f64, v[1] as f64);
        px += vx;
        py += vy;
        kinetic += (vx * vx + vy * vy) / 2.0;
    }
    let mut sq = 0f64;
    for p in &pos {
        let (dx, dy) = (p[0] as f64 - cx, p[1] as f64 - cy);
        sq += dx * dx + dy * dy;
    }
    let spread = (sq / n).sqrt();

    println!("CENTER {} {}", fmt(cx), fmt(cy));
    println!("MOMENTUM {} {}", fmt(px), fmt(py));
    println!("KINETIC {}", fmt(kinetic));
    println!("SPREAD {}", fmt(spread));
    Ok(())
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

