fn parse(text: &str) -> Result<Input, String> {
    let mut tokens = text.split_whitespace();
    let mut next = |what: &str| tokens.next().ok_or_else(|| format!("missing {what}"));

    let count_tok = next("count")?;
    let count: usize = count_tok
        .parse()
        .map_err(|_| format!("bad count: {count_tok}"))?;
    if !(1..=2048).contains(&count) {
        return Err(format!("count out of range: {count}"));
    }
    let steps_tok = next("steps")?;
    let steps: u32 = steps_tok
        .parse()
        .map_err(|_| format!("bad steps: {steps_tok}"))?;
    if steps > 200 {
        return Err(format!("steps out of range: {steps}"));
    }
    let dt_tok = next("dt")?;
    let dt: f64 = dt_tok.parse().map_err(|_| format!("bad dt: {dt_tok}"))?;

    let mut pos = Vec::with_capacity(count);
    let mut vel = Vec::with_capacity(count);
    for k in 0..count {
        let mut field = [0f32; 4];
        for f in field.iter_mut() {
